# Generated by Codebuff for request: make the Hectic Lab AI agent respond as fast
# as possible without breaking existing behaviour or introducing another vector DB.
from __future__ import annotations

import json
import logging
import time
from typing import Any, Dict, List

try:
    from google.genai import errors as genai_errors
except ImportError:
    class _MockAPIError(Exception):
        pass

    genai_errors = type("genai_errors", (), {"APIError": _MockAPIError})

from django.http import StreamingHttpResponse

from rest_framework.response import Response
from rest_framework.views import APIView
from rest_framework.permissions import AllowAny
from rest_framework.throttling import ScopedRateThrottle
from rest_framework import status

from .models import ChatSession, ChatMessage
from .serializer import ChatRequestSerializer, ProjectSearchRequestSerializer
from .utils import (
    build_gemini_context,
    generate_chat_response,
    get_public_projects,
    iter_chat_response,
    search_public_projects,
)

logger = logging.getLogger(__name__)

_RETRYABLE_PROVIDER_CODES = {429, 500, 502, 503, 504}


def _provider_error_payload(exc: genai_errors.APIError) -> Dict[str, Any]:
    """The JSON body shared by the buffered and streamed error responses."""
    if exc.code in _RETRYABLE_PROVIDER_CODES:
        return {
            "error": (
                "Our AI assistant is temporarily experiencing "
                "high demand. Please try again shortly."
            ),
            "code": "AI_PROVIDER_UNAVAILABLE",
            "retryable": True,
        }
    return {
        "error": "The AI service could not process your request.",
        "code": "AI_PROVIDER_ERROR",
        "retryable": False,
    }


def _provider_error_response(exc: genai_errors.APIError) -> Response:
    payload = _provider_error_payload(exc)
    if payload["retryable"]:
        return Response(
            payload,
            status=status.HTTP_503_SERVICE_UNAVAILABLE,
            headers={"Retry-After": "5"},
        )
    return Response(payload, status=status.HTTP_502_BAD_GATEWAY)


def _sse(payload: Dict[str, Any]) -> str:
    """Serialize a single Server-Sent Event frame."""
    return f"data: {json.dumps(payload)}\n\n"


def build_project_sources(prompt: str) -> List[Dict[str, Any]]:
    """
    Build the project source cards returned alongside an answer.

    The plain-text context from build_gemini_context is not a database, so the
    same efficient query is re-run to reconstruct the exact project list it was
    built from. This is shared by the buffered and streamed chat responses.
    """
    projects = get_public_projects()

    results = []
    for project in projects:
        category = (
            project.category.name if project.category else "—"
        )
        results.append(
            {
                "slug": project.slug,
                "title": project.title,
                "category": category,
                "client": project.client,
                "year": project.year,
                "description": project.description,
            }
        )
    return results


# ---------------------------------------------------------------------------
# Chat view (non-streaming, field-compatible with the old response contract).
# ---------------------------------------------------------------------------


class PortfolioChatView(APIView):
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "portfolio_chat"

    def post(self, request):
        serializer = ChatRequestSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        message = serializer.validated_data["message"]
        session_id = serializer.validated_data.get("session_id")
        visitor_token = serializer.validated_data.get("visitor_token")        # Get or create the session exactly as before.
        if session_id and visitor_token:
            session = ChatSession.objects.filter(
                id=session_id,
                visitor_token=visitor_token,
                is_active=True,
            ).first()
            if not session:
                return Response(
                    {"error": "Invalid or expired chat session."},
                    status=status.HTTP_404_NOT_FOUND,
                )
        else:
            session = ChatSession.objects.create()

        # Load the previous conversation for this session.
        # History is returned to the client as sources, so we keep this
        # contract unchanged.
        history_messages = list(
            session.messages.order_by("-created_at")[:10]
        )
        history_messages.reverse()
        history = [
            {"role": item.role, "content": item.content}
            for item in history_messages
        ]

        # Save the user message as before.
        ChatMessage.objects.create(
            session=session,
            role="user",
            content=message,
        )

        request_start = time.perf_counter()

        try:
            # Build the direct-context prompt and measure retrieval.
            stage_start = time.perf_counter()
            # Limit fetched content so a large portfolio never enlarges the
            # prompt proportionally to the whole dataset.
            prompt = build_gemini_context(
                question=message,
                history=history,
                max_history_turns=10,
            )
            db_time = time.perf_counter() - stage_start

            # Generate a single Gemini response.
            stage_start = time.perf_counter()
            answer = generate_chat_response(
                question=message,
                history=history,
                max_history_turns=10,
                context_prompt=prompt,
            )
            gen_time = time.perf_counter() - stage_start

            # Sources are the project cards for the retrieved context.
            sources = build_project_sources(prompt)

            total_time = time.perf_counter() - request_start

            # Save the assistant response as before.
            ChatMessage.objects.create(
                session=session,
                role="assistant",
                content=answer,
                sources=sources,
            )

            logger.info(
                "Portfolio chat: db=%.2fs gen=%.2fs total=%.2fs",
                db_time,
                gen_time,
                total_time,
            )

            return Response(
                {
                    "session_id": str(session.id),
                    "visitor_token": str(session.visitor_token),
                    "answer": answer,
                    "sources": sources,
                    "timing": {
                        "db_ms": round(db_time * 1000, 2),
                        "gemini_ms": round(gen_time * 1000, 2),
                        "total_ms": round(total_time * 1000, 2),
                    },
                },
                status=status.HTTP_200_OK,
            )

        except genai_errors.APIError as exc:
            logger.exception("Gemini API error: %s", exc)
            return _provider_error_response(exc)
        except Exception as exc:
            logger.exception("Portfolio assistant failed: %s", exc)
            return Response(
                {
                    "error": "Something went wrong while generating your response.",
                    "code": "INTERNAL_ASSISTANT_ERROR",
                },
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )


# ---------------------------------------------------------------------------
# Streaming chat (Server-Sent Events).
#
# Identical session handling, context building, source cards and error contract
# to ``PortfolioChatView``; only the response transport differs. The reply is
# emitted token-by-token so the widget can render it as it is generated instead
# of waiting for the complete answer.
# ---------------------------------------------------------------------------


class PortfolioChatStreamView(APIView):
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "portfolio_chat"

    def post(self, request):
        serializer = ChatRequestSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        message = serializer.validated_data["message"]
        session_id = serializer.validated_data.get("session_id")
        visitor_token = serializer.validated_data.get("visitor_token")

        # Resolve the session before streaming so an invalid session is still a
        # normal JSON 404 rather than a broken event stream.
        if session_id and visitor_token:
            session = ChatSession.objects.filter(
                id=session_id,
                visitor_token=visitor_token,
                is_active=True,
            ).first()
            if not session:
                return Response(
                    {"error": "Invalid or expired chat session."},
                    status=status.HTTP_404_NOT_FOUND,
                )
        else:
            session = ChatSession.objects.create()

        history_messages = list(session.messages.order_by("-created_at")[:10])
        history_messages.reverse()
        history = [
            {"role": item.role, "content": item.content}
            for item in history_messages
        ]

        ChatMessage.objects.create(
            session=session,
            role="user",
            content=message,
        )

        prompt = build_gemini_context(
            question=message,
            history=history,
            max_history_turns=10,
        )
        sources = build_project_sources(prompt)

        def event_stream():
            # The meta frame carries the session identifiers (so the client can
            # continue the conversation) and the project source cards.
            yield _sse(
                {
                    "type": "meta",
                    "session_id": str(session.id),
                    "visitor_token": str(session.visitor_token),
                    "sources": sources,
                }
            )

            request_start = time.perf_counter()
            parts: List[str] = []

            try:
                stage_start = time.perf_counter()
                for piece in iter_chat_response(
                    question=message,
                    history=history,
                    max_history_turns=10,
                    context_prompt=prompt,
                ):
                    parts.append(piece)
                    yield _sse({"type": "delta", "text": piece})
                gen_time = time.perf_counter() - stage_start

                answer = "".join(parts).strip()
                if not answer:
                    raise RuntimeError("Gemini returned an empty response.")

                ChatMessage.objects.create(
                    session=session,
                    role="assistant",
                    content=answer,
                    sources=sources,
                )

                logger.info(
                    "Portfolio chat stream: gen=%.2fs total=%.2fs",
                    gen_time,
                    time.perf_counter() - request_start,
                )

                yield _sse(
                    {
                        "type": "done",
                        "timing": {
                            "gemini_ms": round(gen_time * 1000, 2),
                            "total_ms": round(
                                (time.perf_counter() - request_start) * 1000, 2
                            ),
                        },
                    }
                )
            except genai_errors.APIError as exc:
                logger.exception("Gemini API error (stream): %s", exc)
                yield _sse({"type": "error", **_provider_error_payload(exc)})
            except Exception as exc:
                logger.exception("Portfolio assistant stream failed: %s", exc)
                yield _sse(
                    {
                        "type": "error",
                        "error": (
                            "Something went wrong while generating your response."
                        ),
                        "code": "INTERNAL_ASSISTANT_ERROR",
                        "retryable": False,
                    }
                )

        response = StreamingHttpResponse(
            event_stream(),
            content_type="text/event-stream",
        )
        # Keep proxies (and the browser) from buffering the stream.
        response["Cache-Control"] = "no-cache"
        response["X-Accel-Buffering"] = "no"
        return response


# ---------------------------------------------------------------------------
# Natural-language project search.
#
# A visitor describes what they are looking for in their own words ("moody
# black and white fashion work") and Gemini ranks the published projects
# against it. The response is a plain list of project cards, so the work page
# can render it with the components it already has.
# ---------------------------------------------------------------------------


class ProjectSearchView(APIView):
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "portfolio_search"

    def get(self, request):
        serializer = ProjectSearchRequestSerializer(data=request.query_params)
        serializer.is_valid(raise_exception=True)
        query = serializer.validated_data["query"]

        try:
            projects = search_public_projects(query)
        except genai_errors.APIError as exc:
            logger.exception("Gemini project search error: %s", exc)
            return _provider_error_response(exc)
        except Exception as exc:
            logger.exception("Project search failed: %s", exc)
            return Response(
                {
                    "error": "Search is unavailable right now. Please try again shortly.",
                    "code": "INTERNAL_SEARCH_ERROR",
                },
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        return Response(
            {
                "query": query,
                "count": len(projects),
                "results": [
                    {
                        "slug": project.slug,
                        "title": project.title,
                        "client": project.client,
                        "category": (
                            project.category.name if project.category else None
                        ),
                        "year": project.year,
                        "description": project.description,
                        "cover_image": project.cover_image,
                    }
                    for project in projects
                ],
            },
            status=status.HTTP_200_OK,
        )
